def _names(directory):
    return sorted(os.listdir(directory))

def test_r6_empty_source_returns_empty_list(tmp_path):
    src = tmp_path / "src"
    dst = tmp_path / "dst"
    src.mkdir()
    dst.mkdir()

    result = task_func(str(src), str(dst), [".txt"])

    assert result == []
    assert _names(str(dst)) == []
